// Idempotent Payment Mutation Resolver
export async function resolveSubmitPayment(input: { orderId: string; idempotencyKey: string; amountCents: number }) {
  const existingTransaction = await db.query.paymentTransactions.findFirst({
    where: eq(paymentTransactions.idempotencyKey, input.idempotencyKey),
  });
  if (existingTransaction) return { success: true, transaction: existingTransaction };

  const [tx] = await db.insert(paymentTransactions).values({
    orderId: input.orderId,
    idempotencyKey: input.idempotencyKey,
    amountCents: input.amountCents,
    status: 'CAPTURED',
  }).returning();

  await db.update(orders).set({ status: 'PAID' }).where(eq(orders.id, input.orderId));
  return { success: true, transaction: tx };
}
